const kept = [], rejected = [], seen = new Set();
for (const m of ((d && d.matches) || []).slice(0, s.max_matches + 4)) {
  const t = byRef[String(m.product || '').trim()];
  const why = String(m.reason || '').trim();
  const cites = []; let reason = '';
  if (!t) reason = 'not one of the listed products';
  else if (seen.has(t.id)) reason = 'duplicate';
  else if (why.length < 12 || why.length > 400 || /[—<>]/.test(why)) reason = 'reason length or characters';
  else if (!Array.isArray(m.citations) || !m.citations.length) reason = 'no quote';
  const exact = t ? modelRe(t.keys) : null;
  for (const c of (m.citations || [])) {
    const src = bySrc[String(c.source || '').trim()]; const quote = String(c.quote || '').trim();
    if (!src || quote.length < 6 || quote.length > 1500 || !norm(src.full).includes(norm(quote))) { reason = reason || 'quote not found in ' + (c.source || 'its source'); continue; }
    cites.push({ source: src.id, url: src.url, quote });
  }
  if (!reason && !cites.some(c => exact && exact.test(c.quote))) reason = 'exact model not in the quote';
  if (t) seen.add(t.id);
  if (reason) rejected.push({ product: t ? t.title : String(m.product || ''), reason });
  else kept.push({ id: kept.length, target_id: t.id, title: t.title, model: t.model, handle: t.handle, reason: why, citations: cites });
}
const error = r.error ? 'model call failed: ' + String(r.error.message || r.error).slice(0, 200) : (!d ? 'reply was not JSON' : '');
const audit = JSON.stringify({ accessory: { title: p.title, model: p.model },
  candidates: kept.map(({ id, title, model, reason, citations }) => ({ id, product: title, model, reason, quotes: citations.map(c => ({ source: c.source, quote: c.quote })) })),
  sources: p.sources.filter(x => kept.some(k => k.citations.some(c => c.source === x.id))).map(({ id, kind, text }) => ({ id, kind, text })) });
return [{ json: { ...p, prompt: undefined, kept, rejected, error, audit, model_used: s.model } }];

// A match goes to review only with a clear yes on all three checks; a missing verdict is a no
const c = $('Check the quotes').first().json;
const s = $('Match settings').first().json;
const r = $input.first().json;
const fromAudit = r.text !== undefined || r.error !== undefined || r.verdicts !== undefined;
let d = Array.isArray(r.verdicts) ? r : null;
if (fromAudit && !d) { const x = String(r.text || '').replace(/```(?:json)?/g, '').trim(); try { d = JSON.parse(x); } catch (e) { const m = x.match(/\{[\s\S]*\}/); try { d = m ? JSON.parse(m[0]) : null; } catch (e2) {} } }
const verdicts = (d && d.verdicts) || [];
const matches = [], rejected = [...c.rejected];
for (const m of c.kept) {
  if (!fromAudit) { matches.push(m); continue; }
  const v = verdicts.filter(x => Number(x.id) === m.id);
  if (v.length === 1 && v[0].supported === true && v[0].exact_model === true && v[0].is_compatibility === true) matches.push(m);
  else rejected.push({ product: m.title, reason: 'audit: ' + String((v[0] && v[0].reason) || 'no clear verdict').slice(0, 200) });
}
const error = c.error || (fromAudit && r.error ? 'audit call failed: ' + String(r.error.message || r.error).slice(0, 200) : '');
return [{ json: { ...c, audit: undefined, kept: undefined, matches: matches.slice(0, s.max_matches), rejected,
  status: error ? 'failed' : matches.length ? 'review' : 'no_matches', error } }];

// One card per accessory: every match with its reason, quote and source, an Exclude button each, then Approve remaining and Reject all
const d = $json;
const s = $('Match settings').first().json;
const esc = t => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const num = id => String(id).split('/').pop();
const admin = id => 'https://' + s.store_domain + '/admin/products/' + num(id);
const value = JSON.stringify({ a: num(d.accessory_id), r: d.revision });
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: ('Fits: ' + d.title).slice(0, 150) } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: esc(d.model) + ' · ' + d.matches.length + ' to review · ' + d.candidates.length + ' named on the page · ' + esc(d.model_used) }] }
];
for (const m of d.matches) {
  const q = m.citations[0];
  blocks.push({ type: 'section', block_id: 'm_' + num(m.target_id), text: { type: 'mrkdwn', text: ('*<' + admin(m.target_id) + '|' + esc(m.title) + '>*\n' + esc(m.reason) + '\n> ' + esc(q.quote).replace(/\n+/g, ' ') + '\n<' + q.url + '|Manufacturer page>').slice(0, 2900) },
    accessory: { type: 'button', action_id: 'acc_exclude', text: { type: 'plain_text', text: 'Exclude' }, value: JSON.stringify({ a: num(d.accessory_id), t: num(m.target_id), r: d.revision }) } });
}
if (d.rejected.length) {
  const counts = {};
  for (const x of d.rejected) { const k = x.reason.replace(/:.*$/, ''); counts[k] = (counts[k] || 0) + 1; }
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: ':scissors: Dropped ' + d.rejected.length + ': ' + Object.entries(counts).map(([k, n]) => k + ' (' + n + ')').join(', ') }] });
}
blocks.push({ type: 'actions', block_id: 'acc_actions', elements: [
  { type: 'button', style: 'primary', action_id: 'acc_approve', value, text: { type: 'plain_text', text: 'Approve remaining' } },
  { type: 'button', style: 'danger', action_id: 'acc_reject', value, text: { type: 'plain_text', text: 'Reject all' } },
  { type: 'button', action_id: 'acc_link', url: admin(d.accessory_id), text: { type: 'plain_text', text: 'Accessory in Shopify' } }
] });
return [{ json: { ...d, card: JSON.stringify({ channel: s.review_channel, text: 'Accessory matches to review: ' + d.title, blocks, unfurl_links: false, unfurl_media: false }) } }];

// One row per proposed match, carrying the card's channel and timestamp for the thread replies
const d = $('Build the card').first().json;
const post = $('Post the card').first().json;
return d.matches.map(m => ({ json: { accessory_id: d.accessory_id, accessory_title: d.title, target_id: m.target_id, target_title: m.title,
  target_model: m.model, revision: d.revision, reason: m.reason, quote: m.citations[0].quote, source_url: m.citations[0].url,
  slack_channel: post.channel || '', slack_ts: post.ts || '' } }));

const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
if (h['x-slack-retry-num']) return []; // Slack retrying a click we already answered
if (Math.abs(Date.now() / 1000 - Number(h['x-slack-request-timestamp'])) > 300) throw new Error('Stale request');
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || ''; // no URLSearchParams in the Code node
const b = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' ')));
const a = (b.actions || [])[0];
if (!a || !['acc_exclude', 'acc_approve', 'acc_reject'].includes(a.action_id)) return []; // the Shopify link needs nothing
let v = {}; try { v = JSON.parse(a.value || '{}'); } catch (e) {}
const gid = n => n ? 'gid://shopify/Product/' + String(n).split('/').pop() : '';
return [{ json: { base: `v0:${h['x-slack-request-timestamp']}:${raw}`, expected: h['x-slack-signature'],
  user: (b.user || {}).username || (b.user || {}).name || '', action: a.action_id, accessory_id: gid(v.a), target_id: gid(v.t),
  revision: Number(v.r || 0), channel: (b.channel || {}).id, ts: (b.message || {}).ts, blocks: (b.message || {}).blocks || [] } }];

// The same card, with that match struck out and its button gone
const c = $('Read the click').first().json;
const id = 'm_' + c.target_id.split('/').pop();
const blocks = c.blocks.map(b => {
  if (b.block_id !== id) return b;
  const first = String(b.text.text).split('\n')[0].replace(/\*/g, '').replace(/<[^|>]*\|([^>]*)>/g, '$1');
  return { type: 'section', block_id: id, text: { type: 'mrkdwn', text: '~' + first + '~  _excluded by @' + c.user + '_' } };
});
return [{ json: { body: JSON.stringify({ channel: c.channel, ts: c.ts, text: 'Match excluded', blocks }) } }];

// The same card, with the buttons swapped for who decided
const c = $('Read the click').first().json;
const ok = c.action === 'acc_approve';
const left = c.blocks.filter(b => /^m_/.test(b.block_id || '') && b.accessory).length;
const blocks = c.blocks.filter(b => b.block_id !== 'acc_actions').map(b => /^m_/.test(b.block_id || '') && b.accessory ? { ...b, accessory: undefined } : b);
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: ok
  ? ':white_check_mark: Approved by @' + c.user + ': ' + left + ' product' + (left === 1 ? '' : 's') + '. Publishing now.'
  : ':no_entry: Rejected by @' + c.user + '. Shopify was not changed.' }] });
return [{ json: { approved: ok, accessory_id: c.accessory_id, body: JSON.stringify({ channel: c.channel, ts: c.ts, text: (ok ? 'Approved: ' : 'Rejected: ') + $('Get the review').first().json.title, blocks }) } }];

// Is each approved quote still on its page? A page that can't be read now (blocked, or a PDF) is let through: it was checked at Match.
const norm = t => String(t || '').toLowerCase().replace(/[‘’]/g, "'").replace(/[“”]/g, '"').replace(/[‐-―−]/g, '-')
  .replace(/\*\*|\\|[\[\]]/g, '').replace(/\s+/g, ' ').trim();
const ran = $('Publish settings').first().json.recheck_quotes;
const pages = {};
if (ran) $input.all().forEach((it, i) => { const url = $('One row per page').all()[i]?.json.url; if (url) pages[url] = it.json.text || ''; });
return $('Only this accessory').all().map(({ json: m }) => {
  const t = pages[m.source_url];
  const readable = typeof t === 'string' && t.length > 200;
  return { json: { ...m, recheck: !ran ? 'off' : !readable ? 'unreadable' : norm(t).includes(norm(m.quote)) ? 'ok' : 'changed' } };
});

