// Add each approved accessory to its product's list (and the product to the accessory's), keeping what's there
const s = $('Publish settings').first().json;
const matches = $('Check the quotes are still there').all().map(i => i.json);
const nodes = Object.fromEntries((($json.data || {}).nodes || []).filter(Boolean).map(n => [n.id, n]));
const list = mf => { try { const v = JSON.parse((mf && mf.value) || '[]'); return Array.isArray(v) ? v : []; } catch (e) { return []; } };
const comp = {}, compat = {}, outcomes = [];
for (const m of matches) {
  const t = nodes[m.target_id], a = nodes[m.accessory_id];
  const o = { accessory_id: m.accessory_id, target_id: m.target_id, accessory_title: m.accessory_title, target_title: m.target_title,
    slack_channel: m.slack_channel, slack_ts: m.slack_ts };
  if ($json.errors) { outcomes.push({ ...o, status: 'approved', error: 'could not read Shopify: ' + $json.errors.map(e => e.message).join('; ') }); continue; }
  if (m.recheck === 'changed') { outcomes.push({ ...o, status: 'source_changed', error: 'the quote is no longer on ' + m.source_url }); continue; }
  if (!t || !a || t.status !== 'ACTIVE' || a.status !== 'ACTIVE' || !t.publishedAt || !a.publishedAt) {
    outcomes.push({ ...o, status: 'unavailable', error: 'the product or the accessory is not active and published' }); continue; }
  const c = comp[t.id] = comp[t.id] || { before: list(t.complementary), digest: t.complementary ? t.complementary.compareDigest : null, add: [] };
  if (c.before.includes(a.id) || c.add.includes(a.id)) { outcomes.push({ ...o, status: 'pushed', error: 'already there' }); }
  else if (c.before.length + c.add.length >= s.max_complementary) { outcomes.push({ ...o, status: 'list_full', error: t.title + ' already has ' + s.max_complementary + ' complementary products' }); continue; }
  else { c.add.push(a.id); outcomes.push({ ...o, status: 'pushed', error: '' }); }
  if (s.write_compatible_with) {
    const k = compat[a.id] = compat[a.id] || { before: list(a.compatible), digest: a.compatible ? a.compatible.compareDigest : null, add: [] };
    if (!k.before.includes(t.id) && !k.add.includes(t.id)) k.add.push(t.id);
  }
}
const metafields = [
  ...Object.entries(comp).filter(([, c]) => c.add.length).map(([id, c]) => ({ ownerId: id, namespace: 'shopify--discovery--product_recommendation',
    key: 'complementary_products', type: 'list.product_reference', value: JSON.stringify([...c.before, ...c.add]), compareDigest: c.digest })),
  ...Object.entries(compat).filter(([, k]) => k.add.length).map(([id, k]) => ({ ownerId: id, namespace: 'custom',
    key: 'compatible_with', type: 'list.product_reference', value: JSON.stringify([...k.before, ...k.add]), compareDigest: k.digest }))
];
// metafieldsSet takes 25 at a time, and fails the whole call if any compareDigest is stale
const batches = [];
for (let i = 0; i < metafields.length; i += 25) batches.push(metafields.slice(i, i + 25));
return [{ json: { batches, outcomes, writes: metafields.length } }];

// Nothing written: record what would have happened, keeping only the changes
return $json.outcomes.map(o => ({ json: { ...o, status: o.status === 'pushed' ? 'dry_run' : o.status,
  error: o.status === 'pushed' ? 'would add to ' + o.target_title + ($json.writes ? ' (' + $json.writes + ' list writes planned)' : '') : o.error } }));

// A failed call leaves its matches approved, so the next run tries again (a stale compareDigest is read fresh then)
const plan = $('Plan the writes').first().json;
const failedOwners = new Set(); const errs = [];
$input.all().forEach((it, i) => {
  const r = it.json; const ue = (r.data && r.data.metafieldsSet && r.data.metafieldsSet.userErrors) || [];
  if (r.error || r.errors || ue.length) {
    (plan.batches[i] || []).forEach(m => failedOwners.add(m.ownerId));
    errs.push(...(r.errors || []).map(e => e.message), ...ue.map(e => e.message), ...(r.error ? [String(r.error.message || r.error)] : []));
  }
});
const now = new Date().toISOString();
return plan.outcomes.map(o => ({ json: failedOwners.has(o.target_id) || failedOwners.has(o.accessory_id)
  ? { ...o, status: 'approved', error: 'Shopify refused it, will retry: ' + errs.join('; ').slice(0, 300) }
  : { ...o, pushed_at: o.status === 'pushed' ? now : '' } }));

// One thread reply per accessory card, from the rows just saved
const s = $('Publish settings').first().json;
const by = {};
for (const { json: o } of $input.all()) if (o.accessory_id) (by[o.accessory_id] = by[o.accessory_id] || []).push(o);
return Object.values(by).filter(os => os[0].slack_ts).map(os => {
  const line = (st, lead) => { const xs = os.filter(o => o.status === st); return xs.length ? lead + xs.map(o => o.target_title).join(', ') : ''; };
  const text = [line('pushed', ':rocket: Live as a complementary product on '), line('dry_run', ':test_tube: Dry run, would add to '),
    line('list_full', ':no_entry: Not added, the list is full (' + s.max_complementary + ') on '), line('unavailable', ':zzz: Not added, not active and published: '),
    line('source_changed', ':warning: Not added, the quote is gone from the manufacturer page: '),
    line('approved', ':repeat: Shopify refused it, will retry: ')].filter(Boolean).join('\n');
  return { json: { accessory_id: os[0].accessory_id, live: os.some(o => o.status === 'pushed'),
    body: JSON.stringify({ channel: os[0].slack_channel, thread_ts: os[0].slack_ts, text, unfurl_links: false }) } };
});
